func:
flow.set('emailEnabled', msg.payload);
msg.payload = msg.payload ? 'Email: BAT' : 'Email: TAT';
return msg;

var url  = flow.get('SUPABASE_URL');
var key  = flow.get('SUPABASE_ANON_KEY');
msg.headers = {
  'apikey': key,
  'Authorization': 'Bearer ' + key,
  'Content-Type': 'application/json',
  'Prefer': 'return=minimal'
};
msg.url = url + msg._table;
delete msg._table;
return msg;

var val = parseFloat(msg.payload);
if (!isNaN(val)) flow.set('latestTemp', val);
return null;

var val = parseFloat(msg.payload);
if (!isNaN(val)) flow.set('latestHum', val);
return null;

var temp = flow.get('latestTemp');
var hum  = flow.get('latestHum');
if (temp === undefined || hum === undefined) {
  node.warn('Chua co du lieu DHT, bo qua.');
  return null;
}
msg._table  = '/rest/v1/environment_log';
msg.payload = JSON.stringify({
  temperature: temp,
  humidity:    hum,
  fan_state:   flow.get('latestFan') || false
});
return msg;

var enabled = flow.get('emailEnabled');
if (!enabled) { node.warn('Email TAT. Bat tren dashboard.'); return null; }
return msg;

var ownerEmail = 'YOUR_EMAIL@gmail.com';
if (Array.isArray(msg.payload) && msg.payload.length > 0 && msg.payload[0].email) {
    ownerEmail = msg.payload[0].email;
}

var data = msg._rfid_data || {};
var now  = new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});
var emailTopic = '[SafeHome] CANH BAO: The RFID khong hop le!';
var emailBody = 'CANH BAO XAM NHAP SafeHome\n'
            + '========================\n'
            + 'Thoi gian : ' + now + '\n'
            + 'UID the   : ' + (data.uid || 'UNKNOWN') + '\n'
            + 'Ket qua   : DENIED - Khong duoc phep truy cap\n';

// Lay thong tin SMTP tu context
var smtpUser = global.get('smtp_user') || flow.get('smtp_user');
var smtpPass = global.get('smtp_pass') || flow.get('smtp_pass');

if (!smtpUser || !smtpPass) {
    node.warn("Chua cau hinh Email Gui (SMTP). Vui long cau hinh tren Dashboard.");
    return [null, null];
}

var emailMsg = {
    payload: JSON.stringify({
        smtp_user: smtpUser,
        smtp_pass: smtpPass,
        to: ownerEmail,
        subject: emailTopic,
        body: emailBody
    })
};

var supaUrl = flow.get('SUPABASE_URL') || 'https://wfkesifcfgajgymipqcd.supabase.co';
var anonKey = flow.get('SUPABASE_ANON_KEY') || 'sb_publishable_KDECMGj5-HIlQGGUUrYdHg_7b-VojuY';

var notifMsg = {
    url: supaUrl + '/rest/v1/notifications',
    headers: {
        'apikey': anonKey,
        'Authorization': 'Bearer ' + anonKey,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
    },
    payload: {
        event_type: 'rfid_invalid',
        message: 'The RFID khong hop le truy cap vao luc ' + now + ' (UID: ' + (data.uid || 'UNKNOWN') + ')'
    }
};

return [emailMsg, notifMsg];

flow.set('latestTemp', 32.5);
flow.set('latestHum',  75.0);
flow.set('latestFan',  true);
node.warn('Da set: Temp=32.5, Hum=75, Fan=ON');
return msg;

var supaUrl = flow.get('SUPABASE_URL') || 'https://wfkesifcfgajgymipqcd.supabase.co';
var anonKey = flow.get('SUPABASE_ANON_KEY') || 'sb_publishable_KDECMGj5-HIlQGGUUrYdHg_7b-VojuY';
msg.url = supaUrl + '/rest/v1/profiles?role=eq.owner&select=email';
msg.headers = {
  'apikey': anonKey,
  'Authorization': 'Bearer ' + anonKey
};
msg._rfid_data = msg.payload;
return msg;

let userText = msg.payload;

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    "contents": [{
        "parts": [{
            "text": userText
        }]
    }]
};

msg.url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent?key=GEMINI_API_KEY";

return msg;

// 1. Kiểm tra msg.payload có tồn tại không trước, tránh crash khi mất mạng/timeout
if (!msg.payload) {
    msg.payload = "Hệ thống AI đang gặp sự cố: không nhận được phản hồi.";
    return msg;
}

// 2. Bắt riêng lỗi 429 (Quá tải giới hạn API của Google)
if (msg.statusCode == 429 || (msg.payload && msg.payload.error && msg.payload.error.code == 429)) {
    msg.payload = "Trợ lý đang bận xử lý do hệ thống quá tải, vui lòng thử lại sau 1 phút nhé.";
    return msg;
}

// 3. Trích xuất dữ liệu thành công nếu cấu trúc trả về đúng chuẩn của Gemini
if (msg.payload.candidates && msg.payload.candidates.length > 0) {
    msg.payload = msg.payload.candidates[0].content.parts[0].text;
} else {
    // 4. Bắt các lỗi API khác từ Google (VD: 400 sai định dạng, 403 sai key, 404 sai model...)
    let errorDetail = msg.payload.error ? msg.payload.error.message : "Lỗi không xác định";
    msg.payload = "Hệ thống AI đang gặp sự cố: " + errorDetail;
}

return msg;

const rows = msg.payload;

if (!Array.isArray(rows)) {
    node.error("Supabase không trả về mảng dữ liệu", msg);
    return null;
}

const points = rows.reverse().map(row => ({
    time: new Date(row.recorded_at).getTime(),
    label: new Date(row.recorded_at).toLocaleTimeString("vi-VN", {
        hour: "2-digit",
        minute: "2-digit"
    }),
    temperature: Number(row.temperature),
    humidity: Number(row.humidity)
}));

const temperatureStyle = {
    ui_update: {
        chartOptions: {
            color: ["#F44336"],
            textStyle: {
                color: "#000000ff"
            },
            title: {
                textStyle: {
                    color: "#000000ff"
                }
            },
            legend: {
                textStyle: {
                    color: "#000000ff"
                }
            },
            xAxis: {
                axisLabel: { color: "#000000ff" },
                nameTextStyle: { color: "#000000ff" }
            },
            yAxis: {
                axisLabel: { color: "#000000ff" },
                nameTextStyle: { color: "#000000ff" }
            },
            series: [{
                name: "Temperature (°C)",
                type: "line",
                lineStyle: { color: "#F44336" },
                itemStyle: { color: "#F44336" }
            }]
        }
    }
};

const humidityStyle = {
    ui_update: {
        chartOptions: {
            color: ["#2196F3"],
            textStyle: { color: "#000000" },
            title: {
                textStyle: { color: "#000000" }
            },
            legend: {
                textStyle: { color: "#000000ff" }
            },
            xAxis: {
                axisLabel: { color: "#000000" },
                nameTextStyle: { color: "#000000" }
            },
            yAxis: {
                axisLabel: { color: "#000000" },
                nameTextStyle: { color: "#000000" }
            },
            series: [{
                name: "Humidity (%)",
                type: "bar",
                itemStyle: { color: "#2196F3" }
            }]
        }
    }
};

const temperatureData = {
    topic: "Temperature (°C)",
    action: "replace",
    payload: points
};

const humidityData = {
    topic: "Humidity (%)",
    action: "replace",
    payload: points
};

return [
    [temperatureStyle, temperatureData],
    [humidityStyle, humidityData]
];

const { email, password } = msg.payload || {};

if (!email || !password) {
    msg.statusCode = 400;
    msg.payload = {
        ok: false,
        message: "Vui lòng nhập email và mật khẩu."
    };
    return [null, msg]; // đi thẳng tới http response
}

msg.method = "POST";
msg.url = env.get("SUPABASE_URL") +
    "/auth/v1/token?grant_type=password";

msg.headers = {
    "apikey": env.get("SUPABASE_ANON_KEY"),
    "Content-Type": "application/json"
};

msg.payload = { email, password };

return [msg, null]; // gửi sang http request

const { full_name, email, password, re_password } = msg.payload || {};

if (!email || !password || !re_password) {
    msg.statusCode = 400;
    msg.payload = { ok: false, message: "Vui lòng nhập đủ thông tin." };
    return [null, msg];
}

if (password !== re_password) {
    msg.statusCode = 400;
    msg.payload = { ok: false, message: "Mật khẩu nhập lại không khớp." };
    return [null, msg];
}

if (password.length < 6) {
    msg.statusCode = 400;
    msg.payload = { ok: false, message: "Mật khẩu phải có ít nhất 6 ký tự." };
    return [null, msg];
}

msg.method = "POST";
msg.url = env.get("SUPABASE_URL") + "/auth/v1/signup";
msg.headers = {
    "apikey": env.get("SUPABASE_ANON_KEY"),
    "Content-Type": "application/json"
};
msg.payload = {
    email,
    password,
    data: { full_name }
};

return [msg, null];

const result = msg.payload || {};
const status = Number(msg.statusCode || 500);

if (status >= 200 && status < 300 && result.access_token) {
    msg.statusCode = 200;
    msg.payload = {
        ok: true,
        message: "Đăng nhập thành công.",
        access_token: result.access_token,
        refresh_token: result.refresh_token,
        user: {
            id: result.user.id,
            email: result.user.email
        }
    };
} else {
    msg.statusCode = status >= 400 ? status : 401;
    msg.payload = {
        ok: false,
        message: result.msg || result.message || "Email hoặc mật khẩu không đúng."
    };
}

return msg;

const result = msg.payload || {};
const status = Number(msg.statusCode || 500);

// Supabase của bạn trả user trực tiếp; vẫn hỗ trợ cả dạng result.user.
const user = result.user || (result.id ? result : null);

if (status >= 200 && status < 300 && user) {
    msg.statusCode = 201;

    msg.payload = {
        ok: true,
        message: result.confirmation_sent_at
            ? "Đăng ký thành công. Hãy kiểm tra email để xác nhận tài khoản."
            : "Đăng ký thành công. Bạn có thể đăng nhập ngay.",
        user: {
            id: user.id,
            email: user.email
        }
    };
} else {
    msg.statusCode = status >= 400 ? status : 400;

    msg.payload = {
        ok: false,
        message:
            result.msg ||
            result.message ||
            result.error_description ||
            result.error?.message ||
            "Không thể đăng ký tài khoản."
    };
}

return msg;

if (msg.topic === 'smtp_email') {
    flow.set('smtp_user', msg.payload);
} else if (msg.topic === 'smtp_pass') {
    flow.set('smtp_pass', msg.payload);
}
msg.payload = 'Da luu tam thoi!';
return msg;
